INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES.M_SF_COUNT_WRONG', 'MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES', 'Gives one significant figure too many or too few.', '{"question":"48,763 to 2 s.f.","wrong_answer":"48,800","correct_answer":"49,000"}'::jsonb, 'Miscounts the figures kept.', 'The answer 48,800 as a wrong option, with a reason that names the idea.', 'Count again from the first digit: 4, 8 are two figures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES.M_SF_PLACE_ZEROS_DROPPED', 'MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES', 'Leaves out the zeros that hold the place in a whole number.', '{"question":"48,763 to 2 s.f.","wrong_answer":"49","correct_answer":"49,000"}'::jsonb, 'Writes only the significant figures.', 'The answer 49 as a wrong option, with a reason that names the idea.', 'The number must stay about the same size: 49 thousand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES.M_SF_AS_DP', 'MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES', 'Rounds to decimal places when significant figures are asked.', '{"question":"0.004567 to 2 s.f.","wrong_answer":"0.00","correct_answer":"0.0046"}'::jsonb, 'Treats s.f. and d.p. as the same.', 'The answer 0.00 as a wrong option, with a reason that names the idea.', 'Significant figures start at the first non-zero digit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES.M_LEADING_ZEROS_COUNTED', 'MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES', 'Counts the zeros at the front of a small decimal as significant.', '{"question":"0.004567 to 3 s.f.","wrong_answer":"0.00","correct_answer":"0.00457"}'::jsonb, 'Counts every digit after the point.', 'The answer 0.00 as a wrong option, with a reason that names the idea.', 'Zeros in front only hold the place: start at 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_POWER_AS_DIGIT_COUNT', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Uses the number of digits as the power of 10.', '{"question":"45,000 in standard form","wrong_answer":"4.5 × 10⁵","correct_answer":"4.5 × 10⁴"}'::jsonb, 'Counts the digits instead of the places the point moves.', 'The answer 4.5 × 10⁵ as a wrong option, with a reason that names the idea.', 'The point moves 4 places from 45000. to 4.5000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_FRONT_NOT_BETWEEN_1_10', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Writes a front number of 10 or more, or less than 1.', '{"question":"45,000 in standard form","wrong_answer":"45 × 10³","correct_answer":"4.5 × 10⁴"}'::jsonb, 'Moves the point to any place.', 'The answer 45 × 10³ as a wrong option, with a reason that names the idea.', 'The front number is from 1 up to but not including 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_POWER_SIGN_WRONG', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Gives a small number a positive power, or a large number a negative one.', '{"question":"0.0032 in standard form","wrong_answer":"3.2 × 10³","correct_answer":"3.2 × 10⁻³"}'::jsonb, 'Forgets which way the point moved.', 'The answer 3.2 × 10³ as a wrong option, with a reason that names the idea.', 'Smaller than 1 means a negative power.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_POWER_MISCOUNTED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Counts the places the point moves one too many or one too few.', '{"question":"0.0032 in standard form","wrong_answer":"3.2 × 10⁻²","correct_answer":"3.2 × 10⁻³"}'::jsonb, 'Starts counting from the wrong digit.', 'The answer 3.2 × 10⁻² as a wrong option, with a reason that names the idea.', 'Count each jump of the point: three jumps to reach 3.2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_SF_FRONTS_ADDED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Adds the front numbers when two numbers in standard form are multiplied.', '{"question":"(2 × 10³) × (3 × 10⁴): front number","wrong_answer":"5","correct_answer":"6"}'::jsonb, 'Adds because the powers are added.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Multiply the front numbers; add only the powers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_POWERS_MULTIPLIED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Multiplies the powers when multiplying numbers in standard form.', '{"question":"(2 × 10³) × (3 × 10⁴): the power","wrong_answer":"12","correct_answer":"7"}'::jsonb, 'Multiplies everything.', 'The answer 12 as a wrong option, with a reason that names the idea.', '10³ × 10⁴ is 7 tens multiplied: add the powers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_FRONT_NOT_ADJUSTED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Leaves a product front number of 10 or more without moving a 10 into the power.', '{"question":"(4 × 10³) × (5 × 10²)","wrong_answer":"20 × 10⁵","correct_answer":"2 × 10⁶"}'::jsonb, 'Does not check the front number at the end.', 'The answer 20 × 10⁵ as a wrong option, with a reason that names the idea.', '20 = 2 × 10: one more power of 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM.M_ZEROS_MISCOUNTED', 'MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'Writes the ordinary number with the wrong number of zeros.', '{"question":"2 × 10⁶ as an ordinary number","wrong_answer":"20,000,000","correct_answer":"2,000,000"}'::jsonb, 'Writes as many zeros as the power plus one.', 'The answer 20,000,000 as a wrong option, with a reason that names the idea.', 'Move the point 6 places right from 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_POINT_PLACES_PRODUCT', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Puts the point in a product by copying one number''s decimal places.', '{"question":"0.4 × 1.3","wrong_answer":"5.2","correct_answer":"0.52"}'::jsonb, 'Counts the places in one number only.', 'The answer 5.2 as a wrong option, with a reason that names the idea.', 'Add the decimal places of both numbers: 1 + 1 = 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_DEC_LEFT_TO_RIGHT', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Works from left to right, adding before multiplying.', '{"question":"2.5 + 0.4 × 1.3","wrong_answer":"3.77","correct_answer":"3.02"}'::jsonb, 'Reads the question in order.', 'The answer 3.77 as a wrong option, with a reason that names the idea.', 'Multiply first, then add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_DEC_ALL_ADDED', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Adds all the numbers whatever the signs.', '{"question":"2.5 + 0.4 × 1.3","wrong_answer":"4.2","correct_answer":"3.02"}'::jsonb, 'Ignores the operation signs.', 'The answer 4.2 as a wrong option, with a reason that names the idea.', 'Read each sign: × multiplies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_POINTS_NOT_LINED_UP', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Lines up the last digits instead of the points when adding.', '{"question":"2.5 + 0.52","wrong_answer":"0.77","correct_answer":"3.02"}'::jsonb, 'Adds like whole numbers from the right.', 'The answer 0.77 as a wrong option, with a reason that names the idea.', 'Line up the points: tenths under tenths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS.M_DIVISOR_POINT_NOT_MOVED', 'MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'Divides by a decimal without making the divisor a whole number.', '{"question":"1.2 ÷ 0.3","wrong_answer":"0.4","correct_answer":"4"}'::jsonb, 'Divides 1.2 by 3.', 'The answer 0.4 as a wrong option, with a reason that names the idea.', 'Multiply both by 10: 12 ÷ 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE.M_INCOME_FOR_PROFIT', 'MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE', 'Gives the money from selling as the profit.', '{"question":"5 dresses sold at 900 shillings, cloth 2.5 m at 120 a metre each. Profit?","wrong_answer":"4,500","correct_answer":"3,000"}'::jsonb, 'Forgets to take away what was spent.', 'The answer 4,500 as a wrong option, with a reason that names the idea.', 'Profit = money in minus money spent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
